<?php declare(strict_types=1); namespace Haerriz\AgenticCommerce\Model\Tool;
use Haerriz\AgenticCommerce\Model\Wishlist\WishlistService;
class GetWishlist implements ToolInterface { public function __construct(private WishlistService $service){} public function getName():string{return 'get_wishlist';} public function getDefinition():array{return ['type'=>'function','function'=>['name'=>$this->getName(),'description'=>'Get the signed-in customer wishlist.','parameters'=>['type'=>'object','properties'=>[]]]];} public function execute(array $arguments,array $context=[]):array{$w=$this->service->get((array)($context['identity']??[])); return ['wishlist'=>$w,'assistant_message'=>$w['items_count']?(string)__('Your wishlist has %1 item(s).',$w['items_count']):(string)__('Your wishlist is empty.')];} }
